//   Course Clips/ 5 - Lethal Lava Land/Volcano (5,6)/5-5BackGFX / layer 'HL' / frame 3
void frame_4812_0(Activation& scope) {
    stop();
    //
    if (_root["AutoQuality"] == true) {
        if (_root["_quality"] == "HIGH" || _root["_quality"] == "BEST") {
            _root["_quality"] = "MEDIUM";
        } else if (_root["_quality"] == "MEDIUM") {
            _root["_quality"] = "LOW";
        }
    }
    //
    scope["SwitchPL"] = false;
    _root["AreaTextClipF"]("Lethal Lava Land:" + scope["newline"] + "<i>Inside the Volcano</i>", 45);
    _root["warpframe"] = false;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (_root["PauseGame"] == false) {
            _root["WaterAmount"] = Math["max"](_root["WaterAmount"] - 50, 0);
        }
        if (scope.self["warp1"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 1;
        }
        if (scope["warp"] == true && _root["warpframe"] == false) {
            if (scope["warpnum"] == 1) {
                _root["attachMovie"]("uptransition", "uptransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            scope["warp"] = false;
        }
        if (_root["warpframe"] == true) {
            if (scope["warpnum"] == 1) {
                _root["changecourse"]("uptransition2", "5-6", 0, 0, 0, 0);
                //_root.changecourse("righttransition2", "Castle", -1300, 100, -1300, 100);
            }
            //_root.warpframe = false;
        }
        return undefined;
    });
}

