//   Course Clips/ 5 - Lethal Lava Land/Volcano (5,6)/5-6FrontLava / layer 'Layer 2' / frame 1
void frame_4836_0(Activation& scope) {
    scope["count"] = 0;
    if (_root["CharHP"] <= 0) {
        _root["CharHP"] = 8;
        _root["Course"]["Char"]["attack"] = false;
    }
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        _root["Course"]["BackGFX"]["StartClip"]["_y"] = -50;
        if (scope["count"] < 128 || _root["PauseGame"] == false) {
            scope["count"]++;
        }
        // Put the cinema stuff here
        if (scope["count"] > 96) {
            if (_root["PauseGame"] == false) {
                if (scope["count"] == 128) {
                    _root["StartBossMusic"]();
                }
                if (scope["count"] > 128) {
                    scope["diff"] = (_root["currentCamY"]) - (scope["_y"] + scope["_parent"]["_y"]);
                    scope["diff"] = Math["min"](0, scope["diff"]);
                    scope["diff"] = Math["max"](-1000, scope["diff"]);
                    scope["_y"] -= 0.3 - (scope["diff"] / 100);
                    scope["_y"] = Math["max"](scope["_y"], -1100);
                } else {
                    if (scope["count"] % 2 == 0) {
                        _root["MoveAllPlats"](3, 0);
                    } else {
                        _root["MoveAllPlats"](-3, 0);
                    }
                }
            }
        } else {
            _root["Controll"] = false;
            _root["PauseGame"] = false;
            if (scope["count"] > 32) {
                _root["Camspeed"] = 15;
                _root["MaxCamspeed"] = 25;
                _root["Camcenter"] = _root["Course"]["BackGFX"]["Target1"];
            }
        }
        if (scope["count"] == 32) {
            _root["StopBGsong"]();
        }
        if (scope["count"] == 128) {
            _root["Controll"] = true;
            _root["Camcenter"] = "none";
        }
        return undefined;
    });
}

